function registerAdAccountsApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/analytics", OpenAPI.Servers.middleware(impl, ad_account_analytics_read, ad_account_analytics_validate, ad_account_analytics_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/targeting_analytics", OpenAPI.Servers.middleware(impl, ad_account_targeting_analytics_get_read, ad_account_targeting_analytics_get_validate, ad_account_targeting_analytics_get_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts", OpenAPI.Servers.middleware(impl, ad_accounts_create_read, ad_accounts_create_validate, ad_accounts_create_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}", OpenAPI.Servers.middleware(impl, ad_accounts_get_read, ad_accounts_get_validate, ad_accounts_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts", OpenAPI.Servers.middleware(impl, ad_accounts_list_read, ad_accounts_list_validate, ad_accounts_list_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/reports/brand_category_sku", OpenAPI.Servers.middleware(impl, analytics_create_conversion_product_report_read, analytics_create_conversion_product_report_validate, analytics_create_conversion_product_report_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/mmm_reports", OpenAPI.Servers.middleware(impl, analytics_create_mmm_report_read, analytics_create_mmm_report_validate, analytics_create_mmm_report_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/reports", OpenAPI.Servers.middleware(impl, analytics_create_report_read, analytics_create_report_validate, analytics_create_report_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/ad_accounts/{ad_account_id}/templates/{template_id}/reports", OpenAPI.Servers.middleware(impl, analytics_create_template_report_read, analytics_create_template_report_validate, analytics_create_template_report_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/reports/brand_category_sku", OpenAPI.Servers.middleware(impl, analytics_get_conversion_product_report_read, analytics_get_conversion_product_report_validate, analytics_get_conversion_product_report_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/mmm_reports", OpenAPI.Servers.middleware(impl, analytics_get_mmm_report_read, analytics_get_mmm_report_validate, analytics_get_mmm_report_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/reports", OpenAPI.Servers.middleware(impl, analytics_get_report_read, analytics_get_report_validate, analytics_get_report_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/ad_accounts/{ad_account_id}/sandbox", OpenAPI.Servers.middleware(impl, sandbox_delete_read, sandbox_delete_validate, sandbox_delete_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/ad_accounts/{ad_account_id}/templates", OpenAPI.Servers.middleware(impl, templates_list_read, templates_list_validate, templates_list_invoke; optional_middlewares...))
    return router
end
